python3 -c "
import RNA
t='....((....((....((....((..((..((...))..))....))......)).......)).........)).............'
base='AAAAGGGAAAGGGAAAGGAAAAGGAAGGAAGCGAAGCAACCAAAACCAAAAAGCCAAAAAAACCAAAAAAAACCCAAAAAAAAAAAAA'
def score(s):
    fc=RNA.fold_compound(s); m,e=fc.mfe(); return RNA.bp_distance(m,t),m
# break pair 6-72: position 6=G, 72=C. Try changing 6 or 72 to A/U mismatch
best=base; bd,_=score(base)
print('start',bd)
for p in [6,72,7,71,5,73]:
    for c in 'ACGU':
        s=list(base); s[p]=c; c2=''.join(s)
        d,m=score(c2)
        if d<bd: bd=d; best=c2; print('improve',p,c,bd,m)
# also try combos
import itertools
for p1,p2 in itertools.combinations([5,6,7,71,72,73,4,74],2):
    for c1 in 'ACGU':
        for c2 in 'ACGU':
            s=list(base); s[p1]=c1; s[p2]=c2
            c=''.join(s); d,m=score(c)
            if d<bd: bd=d; best=c; print('combo',p1,c1,p2,c2,bd)
print('best',bd); print(best)
fc=RNA.fold_compound(best); print(fc.mfe()[0])
"
